function solve(n) {
  if (n <= 0) return 0;
  const placed = [];
  let count = 0;
  function safe(row, col) {
    for (let i = 0; i < placed.length; i++) {
      if (placed[i] === col) return false;
      if (Math.abs(placed[i] - col) === Math.abs(i - row)) return false;
    }
    return true;
  }
  function place(row) {
    if (row === n) {
      count++;
      return;
    }
    for (let col = 0; col < n; col++) {
      if (safe(row, col)) {
        placed.push(col);
        place(row + 1);
        placed.pop();
      }
    }
  }
  place(0);
  return count;
}

function solve(n) {
  if (n <= 0) return 0;
  const full = (1 << n) - 1;
  let count = 0;
  function place(cols, diagDown, diagUp) {
    if (cols === full) {
      count++;
      return;
    }
    let options = full & ~(cols | diagDown | diagUp);
    while (options !== 0) {
      const bit = options & -options;
      options -= bit;
      place(cols | bit, ((diagDown | bit) << 1) & full, (diagUp | bit) >> 1);
    }
  }
  place(0, 0, 0);
  return count;
}
